63	/* -------- Memory ---------- */
64	
65	void * hosted_memcpy(void* dest, const void* src, uint32_t size)
66	{
67		if (size && (!dest || !src)) {
68			if (!dest)
69				ESP_LOGE(TAG, "%s:%u dest is NULL\n", __func__, __LINE__);
70			if (!src)
71				ESP_LOGE(TAG, "%s:%u dest is NULL\n", __func__, __LINE__);
72	
73			assert(dest);
74			assert(src);
75			return NULL;
76		}
77	
78		return memcpy(dest, src, size);
79	}
80	
81	void * hosted_memset(void* buf, int val, size_t len)
82	{
83		return memset(buf, val, len);
84	}
85	
86	void* hosted_malloc(size_t size)
87	{
88		/* without alignment */
89		return malloc(size);
90	}
91	
92	void* hosted_calloc(size_t blk_no, size_t size)
93	{
94		void* ptr = (void*)hosted_malloc(blk_no*size);
95		if (!ptr) {
96			return NULL;
97		}
98	
99		hosted_memset(ptr, 0, blk_no*size);
100		return ptr;
101	}
102	
103	void hosted_free(void* ptr)
104	{
105		if(ptr) {
106			free(ptr);
107			ptr=NULL;
108		}
109	}
110	
111	void *hosted_realloc(void *mem, size_t newsize)
112	{
113		if (newsize == 0) {
114			HOSTED_FREE(mem);
115			return NULL;
116		}
117	
118		/* Use libc realloc: it knows the old allocation size and copies only the
119		 * valid bytes. The previous malloc + memcpy(newsize) over-read `mem` by
120		 * the (newsize - oldsize) growth delta — `mem` only held oldsize bytes —
121		 * which faults when the old block sits at the top of RAM (the serial RX
122		 * reassembly buffer in serial_ll_if.c grows through this realloc).
123		 * hosted_malloc/HOSTED_FREE are plain malloc/free, so realloc is a safe
124		 * drop-in on the same heap. */
125		return realloc(mem, newsize);
126	}
127	
128	void *hosted_malloc_align(size_t size, size_t align)
129	{
130		void *ptr = NULL;
131	
132	#if CONFIG_ESP_HOSTED_MEMPOOL_PREFER_SPIRAM
133		/* On targets where GDMA can reach PSRAM through cache (e.g. ESP32-P4),
134		 * prefer DMA-capable SPIRAM to preserve scarce internal RAM. */
135		ptr = heap_caps_aligned_alloc(align, size,
136				MALLOC_CAP_SPIRAM | MALLOC_CAP_DMA | MALLOC_CAP_8BIT);
137	#endif
138		if (!ptr) {
139			ptr = heap_caps_aligned_alloc(align, size,
140					MALLOC_CAP_INTERNAL | MALLOC_CAP_DMA | MALLOC_CAP_8BIT);
141		}
142		return ptr;
143	}
144	
145	void hosted_free_align(void* ptr)
146	{
147		free(ptr);
148	}
