84	static void transport_driver_event_handler(uint8_t event)
85	{
86		switch(event)
87		{
88			case TRANSPORT_TX_ACTIVE:
89			{
90				/* Initiate control path now */
91				ESP_LOGI(TAG, "Base transport is set-up, TRANSPORT_TX_ACTIVE");
92				if (transport_esp_hosted_up_cb)
93					transport_esp_hosted_up_cb();
94				transport_state = TRANSPORT_TX_ACTIVE;
95				break;
96			}
97	
98			case TRANSPORT_INACTIVE:
99			case TRANSPORT_RX_ACTIVE:
100				transport_state = event;

100		/*TODO: add rpc channel from here
101		ch = esp_hosted_add_channel(&config, &tx_cb, esp_wifi_remote_rpc_channel_rx);
102		esp_wifi_remote_rpc_channel_set(ch, tx_cb); */
103	
104		/* Add two other channels for the two WiFi interfaces (STA, softAP) in plain text */
105		config.secure = false;
106		config.if_type = ESP_STA_IF;
107		sta_ch = esp_hosted_add_channel(&config, &tx_cb, esp_wifi_remote_channel_rx);
108		esp_wifi_remote_channel_set(WIFI_IF_STA, sta_ch, tx_cb);
109	
110	
111		config.secure = false;
112		config.if_type = ESP_AP_IF;
113		ap_ch = esp_hosted_add_channel(&config, &tx_cb, esp_wifi_remote_channel_rx);
114		esp_wifi_remote_channel_set(WIFI_IF_AP, ap_ch, tx_cb);
115	
116		return ESP_OK;
117	}
