138	int esp_hosted_init(void)
139	{
140		if (esp_hosted_init_done)
141			return ESP_OK;
142	
143		set_host_modules_log_level();
144	
145		//create_esp_hosted_transport_up_sem();
146		ESP_LOGI(TAG, "ESP-Hosted starting. Hosted_Tasks: prio:%u, stack: %u RPC_task_stack: %u",
147				DFLT_TASK_PRIO, DFLT_TASK_STACK_SIZE, RPC_TASK_STACK_SIZE);
148		if (esp_hosted_is_config_valid()) {
149			ESP_LOGW(TAG, "ESP-Hosted config valid; reuse existing config");
150		} else {
151			ESP_ERROR_CHECK(esp_hosted_set_default_config());
152		}
153		ESP_ERROR_CHECK(add_esp_wifi_remote_channels());
154		ESP_ERROR_CHECK(setup_transport(transport_active_cb));
155		ESP_ERROR_CHECK(rpc_init());
156		rpc_register_event_callbacks();
157	
158		esp_hosted_init_done = 1;
159		return ESP_OK;
